package correlation

func ChainCatalog() []RuleDescription {
	out := []RuleDescription{}
	for _, r := range []struct{ id, title, summary, condition string }{
		{"chain.domain_account_hosts", "Доменная учётная запись на нескольких узлах", "Сетевая активность одной доменной учётной записи на разных управляемых узлах.", "Успешные сетевые/RDP-входы 4624 (тип 3/10) с одинаковым SID доменной учётной записи на минимум 3 различных агентах и активах за 15 минут."},
		{"chain.logon_guid_hosts", "Общий Logon GUID на нескольких узлах", "Несколько узлов сообщили один ненулевой Logon GUID и SID доменной учётной записи.", "Сетевые/RDP-входы с одинаковыми SID и ненулевым Logon GUID на минимум 2 узлах за 15 минут."},
		{"chain.ssh_key_hosts", "SSH-ключ использован на нескольких узлах", "Один публичный SSH-ключ использован для успешного входа на разные узлы. Имена пользователей могут различаться.", "Accepted publickey с одинаковым корректным SHA256-отпечатком ключа минимум на 3 узлах за 15 минут. Источник journald: UID 0 и исполняемый файл sshd/sshd-session."},
		{"chain.remote_logon_audit_clear", "Входы на разных узлах и очистка аудита в сеансе", "События одной доменной учётной записи на разных узлах предшествуют очистке аудита в локальном сеансе входа.", "В течение 30 минут: успешный сетевой/RDP-вход на другом узле → вход на текущем узле с тем же SID → Security 1102 с тем же SID и локальным Logon ID. Минимум 2 узла; строгий порядок времени."},
	} {
		out = append(out, RuleDescription{ID: r.id, Version: 1, Title: r.title, Summary: r.summary, Condition: r.condition, Scope: "Различные аутентифицированные AgentID и AssetID. Каждый участник проходит группы и исключения политики. Порог 2–20 — число различных узлов; окно и подавление настраиваются. Подавление общее для ключа между узлами.", Limitations: "Идентификаторы сообщены источниками, а не подтверждены отдельным запросом в AD. Локальные/системные/машинные учётные записи не объединяются по SID; имена и IP не служат межузловым ключом. Это наблюдения, не доказательство прямого перемещения или атаки. Logon ID ограничен агентом/активом и может повторяться после перезагрузки. До 200 записей / 8 МиБ истории, 20 узлов + очистка. Поздние события не пересчитывают старые срабатывания, архивы не читаются; старые нормализованные события автоматически не обогащаются. Автоматическое active response не запускается.", FalsePositives: []string{"Штатное доменное администрирование, Kerberos SSO", "Общий ключ автоматизации или разрешённая работа на нескольких серверах"}, Investigation: []string{"Просмотрите цепочку, типы связей и исходные события каждого узла", "Уточните владельца SID/ключа и согласованные работы", "Сопоставьте сетевые соединения, команды и время перезагрузок перед выводом о перемещении"}, References: []string{"https://learn.microsoft.com/en-us/previous-versions/windows/it-pro/windows-10/security/threat-protection/auditing/event-4624", "https://learn.microsoft.com/en-us/previous-versions/windows/it-pro/windows-10/security/threat-protection/auditing/event-1102"}})
	}
	return out
}
